/** A T-ARMS-FORMS probe as the frozen-shape literal reads it. */
const armFormShape = (form: ArmForm): string =>
  `${form.id} ${form.label} [${form.into}${form.retype === undefined ? "" : ` retyped ${form.retype}`}${form.rebind === undefined ? "" : ` rebound ${form.rebind}`}]: ${JSON.stringify(form.declaration ?? "")} + ${JSON.stringify(form.code ?? "")} -> +${form.added.join(" +") || "none"} at ${form.at}, -${form.drops ?? 0}; unread ${form.unread.join(" | ") || "none"}`;

